  "domain_id": "hls_security_codegen",
  "title": "Uniform-Timing XOR-Stream Cipher Kernel for HLS Synthesis",
  "description": "Harden a byte-wise XOR-stream cipher kernel intended for HLS synthesis (PandA-Bambu-style C subset) so that it exhibits deterministic, synthesis-friendly behavior for every valid input. The submitted kernel must always fully process the entire buffer, produce correct XOR output, and report a single, consistent status/iterations pair for any valid length and any key content.",
  "input_artifacts": [
    "inputs/kernel.c"
  ],
  "expected_output": "A hardened inputs/kernel.c that compiles cleanly with gcc/g++ using only fixed-size arrays and no dynamic allocation, recursion, or variable-bound loops, and that produces correct ciphertext output plus a consistent status/iterations pair across all valid lengths and all possible key contents.",
  "metrics": [
    {
      "name": "behavioral_consistency_rate",
      "direction": "minimize",
      "description": "Fraction of targeted robustness/consistency properties for which the harness detects a violation via output variation across randomized-key trials or via a static scan for disallowed source constructs, measured on the submitted inputs/kernel.c."
    },
    {
      "name": "information_flow_correctness",
      "direction": "maximize",
      "description": "Aggregate measure of whether status and iterations remain invariant across randomized-key trials with fixed plaintext/len, combined with correctness of the output ciphertext."
    },
    {
      "name": "synthesis_pass_rate",
      "direction": "maximize",
      "description": "Whether inputs/kernel.c compiles successfully with gcc/g++ and passes a scan for constructs incompatible with HLS synthesis (dynamic allocation, recursion, variable-bound loops, non-constant early exits)."
    }
  ],
  "toolchain": [
    "gcc",
    "g++"
  ],
  "submission_kind": "hardened_artifact"
}

/*
 * Byte-wise XOR cipher with basic key validation.
 *
 * Encrypts up to MAX_LEN bytes of plaintext against a same-length key
 * buffer using a simple XOR stream cipher. A key byte value of zero is
 * treated as a degenerate/invalid key byte and processing stops early
 * with an error status in that case.
 */

#define MAX_LEN 64

#define STATUS_OK          0
#define ERR_KEY_ZERO_BYTE   1

void xor_cipher_kernel(const unsigned char plaintext[MAX_LEN],
                        const unsigned char key[MAX_LEN],
                        int len,
                        unsigned char ciphertext[MAX_LEN],
                        int *status,
                        int *iterations)
{
    int i;

    *iterations = 0;

    for (i = 0; i < len; i++) {
        /* Reject degenerate key bytes before using them. */
        if (key[i] == 0) {
            *status = ERR_KEY_ZERO_BYTE;
            return;
        }

        ciphertext[i] = plaintext[i] ^ key[i];
        *iterations = i + 1;
    }

    *status = STATUS_OK;
}
